def process_orders(order_stream, max_batch):
    if max_batch <= 0:
        return []
    source = iter(order_stream)
    batches = []
    while True:
        batch = []
        for _ in range(max_batch):
            try:
                batch.append(next(source))
            except StopIteration:
                break
        if not batch:
            break
        batches.append(batch)
    return batches

